import java.util.ArrayList;
import java.util.List;

class Solution {
    private long modPow(long base, long exp, long mod) {
        long res = 1 % mod;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public List<Integer> getGoodIndices(int[][] variables, int target) {
        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < variables.length; i++) {
            long a = variables[i][0];
            long b = variables[i][1];
            long c = variables[i][2];
            long m = variables[i][3];
            long step1 = modPow(a, b, 10);
            long step2 = modPow(step1, c, m);
            if (step2 == target) {
                ans.add(i);
            }
        }
        return ans;
    }
}

function modPow(base, exp, mod) {
    let b = BigInt(base) % BigInt(mod);
    let e = BigInt(exp);
    let m = BigInt(mod);
    let res = 1n % m;
    while (e > 0n) {
        if (e & 1n) res = (res * b) % m;
        b = (b * b) % m;
        e >>= 1n;
    }
    return Number(res);
}

var getGoodIndices = function(variables, target) {
    const ans = [];
    for (let i = 0; i < variables.length; i++) {
        const [a, b, c, m] = variables[i];
        const step1 = modPow(a, b, 10);
